package com.rustypayments.modern;

import com.rustypayments.PaymentCalendar;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.time.temporal.TemporalAdjusters;
import java.util.Set;

public class ModernPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final Set<MonthDay> HOLIDAYS = Set.of(
            MonthDay.of(Month.JANUARY, 1),
            MonthDay.of(Month.JANUARY, 6),
            MonthDay.of(Month.MAY, 1),
            MonthDay.of(Month.MAY, 3),
            MonthDay.of(Month.AUGUST, 15),
            MonthDay.of(Month.NOVEMBER, 1),
            MonthDay.of(Month.NOVEMBER, 11),
            MonthDay.of(Month.DECEMBER, 25),
            MonthDay.of(Month.DECEMBER, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        if (date == null) {
            throw new IllegalArgumentException("Date cannot be null");
        }
        try {
            LocalDate d = LocalDate.parse(date);
            return isBusinessDay(d);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date format: " + date, e);
        }
    }

    @Override
    public String processingDate(String submittedAt) {
        if (submittedAt == null) {
            throw new IllegalArgumentException("Instant cannot be null");
        }
        try {
            ZonedDateTime zdt = ZonedDateTime.parse(submittedAt).withZoneSameInstant(BANK_ZONE);
            LocalDate date = zdt.toLocalDate();
            LocalTime time = zdt.toLocalTime();

            if (isBusinessDay(date) && !time.isAfter(LocalTime.of(16, 0, 0))) {
                return date.toString();
            } else {
                return nextBusinessDay(date).toString();
            }
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid instant format: " + submittedAt, e);
        }
    }

    @Override
    public String settlementDate(String submittedAt) {
        if (submittedAt == null) {
            throw new IllegalArgumentException("Instant cannot be null");
        }
        try {
            ZonedDateTime zdt = ZonedDateTime.parse(submittedAt).withZoneSameInstant(BANK_ZONE);
            LocalDate procDate = getProcessingDate(zdt.toLocalDate(), zdt.toLocalTime());
            return nextBusinessDay(procDate).toString();
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid instant format: " + submittedAt, e);
        }
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        if (dueDate == null || paidAt == null) {
            throw new IllegalArgumentException("Arguments cannot be null");
        }
        try {
            LocalDate due = LocalDate.parse(dueDate);
            ZonedDateTime paidZdt = ZonedDateTime.parse(paidAt).withZoneSameInstant(BANK_ZONE);
            LocalDate paid = paidZdt.toLocalDate();
            long diff = ChronoUnit.DAYS.between(due, paid);
            return (int) Math.max(0, diff);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid format", e);
        }
    }

    @Override
    public String addMonths(String date, int months) {
        if (date == null) {
            throw new IllegalArgumentException("Date cannot be null");
        }
        try {
            LocalDate d = LocalDate.parse(date);
            boolean startsAtEndOfMonth = d.equals(d.with(TemporalAdjusters.lastDayOfMonth()));
            LocalDate result = d.plusMonths(months);
            if (startsAtEndOfMonth) {
                result = result.with(TemporalAdjusters.lastDayOfMonth());
            }
            return result.toString();
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date format: " + date, e);
        }
    }

    private LocalDate getProcessingDate(LocalDate date, LocalTime time) {
        if (isBusinessDay(date) && !time.isAfter(LocalTime.of(16, 0, 0))) {
            return date;
        } else {
            return nextBusinessDay(date);
        }
    }

    private boolean isBusinessDay(LocalDate date) {
        DayOfWeek dow = date.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
            return false;
        }
        return !HOLIDAYS.contains(MonthDay.from(date));
    }

    private LocalDate nextBusinessDay(LocalDate date) {
        LocalDate current = date;
        do {
            current = current.plusDays(1);
        } while (!isBusinessDay(current));
        return current;
    }
}

